#program_export
Answer :: () -> s32 {
    if Text.LowerASCII(cast(u8)65) != cast(u8)97 { return 1 }
    return 0
}

#program_export
Answer :: () -> s32 {
    value: s32 = 2147483647
    return value + 1
}

Check :: () -> s32 {
    bytes: [1]u8 = .[97]
    {
        text := TextView(bytes[:])
        if text.count != 1 { return 1 }
    }
    bytes[0] = cast(u8)98
    return cast(s32)bytes[0]
}

